import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788283396000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><p>Six variables, all read once at startup. There is no config file.</p><h2 id="hetzner-api-token" tabindex="-1"><code>HETZNER_API_TOKEN</code> <a class="header-anchor" href="#hetzner-api-token" aria-label="Permalink to “HETZNER_API_TOKEN”">​</a></h2><p><strong>Required.</strong> Hetzner Cloud API token for the project that holds the zones.</p><p>Create it in the <a href="https://console.hetzner.com" target="_blank" rel="noreferrer">Cloud Console</a> under <strong>your project → Security → API tokens</strong>. Choose <strong>Read &amp; Write</strong> for the full tool set, <strong>Read</strong> for the query tools only.</p><ul><li>Sent as <code>Authorization: Bearer …</code> on every request.</li><li>Deleted from <code>process.env</code> once read.</li><li>Never logged, never included in an error message or a tool result.</li></ul><p>Without it the server still starts, completes the MCP handshake and lists all tools — registries and sandbox inspectors need that — but every call fails with setup instructions and nothing reaches the API.</p><div class="danger custom-block"><p class="custom-block-title custom-block-title-default">DANGER</p><p>A token from the old DNS Console (<code>dns.hetzner.com</code>) does not work. That API was shut down in May 2026.</p></div><h2 id="hetzner-read-only" tabindex="-1"><code>HETZNER_READ_ONLY</code> <a class="header-anchor" href="#hetzner-read-only" aria-label="Permalink to “HETZNER_READ_ONLY”">​</a></h2><p><strong>Optional</strong>, default <code>false</code>. Accepts <code>true</code>, <code>1</code> or <code>yes</code>, case-insensitively.</p><p>When set, only these seven tools are registered:</p><p><code>list_zones</code> · <code>get_zone</code> · <code>export_zonefile</code> · <code>list_rrsets</code> · <code>get_rrset</code> · <code>list_zone_actions</code> · <code>get_zone_action</code></p><p>The write tools are not registered at all, so a client asking for <code>delete_zone</code> gets a protocol-level &quot;tool not found&quot;. This is not a call-time refusal — there is no code path from a write request to the API.</p><h2 id="elicitation" tabindex="-1"><code>ELICITATION</code> <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p><strong>Optional</strong>, default <code>true</code>. Whether a client that <em>can</em> show a dialog is asked before a guarded tool acts. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable here, and the first is worth reading twice:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> Where <code>HETZNER_READ_ONLY</code> is deliberately generous — <code>true</code>, <code>1</code> or <code>yes</code> — this one takes <code>true</code> or <code>false</code> and stops the server with exit code 1 on anything else. It is the only variable of this family that defaults to <em>on</em>, and a typo that fell back to the default would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively. It is read <em>after</em><code>HETZNER_API_TOKEN</code> is deleted from <code>process.env</code>, so the fatal path cannot leave the token sitting there for a crash reporter.</p><h2 id="hetzner-api-base-url" tabindex="-1"><code>HETZNER_API_BASE_URL</code> <a class="header-anchor" href="#hetzner-api-base-url" aria-label="Permalink to “HETZNER_API_BASE_URL”">​</a></h2><p><strong>Optional</strong>, default <code>https://api.hetzner.cloud/v1</code>. Trailing slashes are stripped.</p><p>Intended for pointing at a local mock during development. Validated before anything is sent, because the token goes to whatever this names:</p><table tabindex="0"><thead><tr><th>Rule</th><th>On violation</th></tr></thead><tbody><tr><td>Must parse as a URL</td><td>exit</td></tr><tr><td>Must be <code>https</code> (<code>http</code> only for loopback hosts)</td><td>exit</td></tr><tr><td>Must not contain credentials (<code>https://user:pass@…</code>)</td><td>exit</td></tr><tr><td>Non-default host</td><td>warning</td></tr></tbody></table><p>Loopback hosts are <code>localhost</code>, <code>127.0.0.1</code> and <code>[::1]</code>.</p><p>The value is never printed back on a parse failure — a malformed URL can still contain a <code>user:token@</code> part, and startup messages end up in client logs.</p><p>Also deleted from <code>process.env</code> once read.</p><h2 id="hetzner-allow-tools" tabindex="-1"><code>HETZNER_ALLOW_TOOLS</code> <a class="header-anchor" href="#hetzner-allow-tools" aria-label="Permalink to “HETZNER_ALLOW_TOOLS”">​</a></h2><p><strong>Optional</strong>, unset by default — then every tool the mode allows is registered.</p><p>A comma-separated list of entries. Each entry is either an exact tool name or a prefix followed by a single trailing <code>*</code>:</p><table tabindex="0"><thead><tr><th>Value</th><th>Registers</th></tr></thead><tbody><tr><td><code>essential</code></td><td>the curated preset of eight (below)</td></tr><tr><td><code>list_zones,get_zone</code></td><td>exactly those two</td></tr><tr><td><code>list_*</code></td><td><code>list_rrsets</code>, <code>list_zone_actions</code>, <code>list_zones</code></td></tr><tr><td><code>essential,update_zone</code></td><td>the preset plus one more</td></tr><tr><td><code>*</code></td><td>everything — the same as leaving it unset</td></tr></tbody></table><p>The preset is:</p><p><code>list_zones</code> · <code>get_zone</code> · <code>list_rrsets</code> · <code>get_rrset</code> · <code>create_rrset</code> · <code>set_records</code> · <code>delete_rrset</code> · <code>export_zonefile</code></p><p>Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>HETZNER_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names. So does a malformed pattern such as <code>*_zone</code> or <code>list_*_x</code>, where the <code>*</code> is not the last character. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause.</p><p>Under <code>HETZNER_READ_ONLY</code>, an exact write-tool name here is an error naming the read-only setting rather than &quot;unknown tool&quot;; a <em>pattern</em> covering write tools is accepted and merely contributes nothing, with a warning on stderr.</p><h2 id="hetzner-deny-tools" tabindex="-1"><code>HETZNER_DENY_TOOLS</code> <a class="header-anchor" href="#hetzner-deny-tools" aria-label="Permalink to “HETZNER_DENY_TOOLS”">​</a></h2><p><strong>Optional</strong>, unset by default. Same syntax as <code>HETZNER_ALLOW_TOOLS</code>, minus the <code>essential</code> keyword.</p><p>Subtracted from whatever <code>HETZNER_ALLOW_TOOLS</code> selected — or from every tool, if that one is unset. <code>HETZNER_DENY_TOOLS=delete_zone,import_zonefile</code> is the usual shape: keep everything, drop the two that cannot be undone.</p><p>A deny entry that matches no tool aborts startup, on the same reasoning. It may match tools that are already absent — denying a write tool while <code>HETZNER_READ_ONLY</code> is set is how a defensive list is written, and is not an error.</p><p>If both lists remove everything, the server refuses to start rather than offering an empty tool list.</p><h2 id="not-configurable" tabindex="-1">Not configurable <a class="header-anchor" href="#not-configurable" aria-label="Permalink to “Not configurable”">​</a></h2><p>For completeness, the constants you might otherwise look for:</p><table tabindex="0"><thead><tr><th>Behaviour</th><th>Value</th></tr></thead><tbody><tr><td>Request timeout</td><td>30 s</td></tr><tr><td>Redirect handling</td><td>refused</td></tr><tr><td>Confirmation token TTL</td><td>5 minutes, single use</td></tr><tr><td>Pending confirmation tokens</td><td>100 max, oldest evicted</td></tr><tr><td>Per-value truncation</td><td>4 000 characters</td></tr><tr><td>Per-result truncation</td><td>200 000 characters</td></tr><tr><td>Error body truncation</td><td>2 000 characters; HTML dropped</td></tr><tr><td>Redacted key pattern</td><td><code>tsig_key</code>, <code>token</code>, <code>secret</code>, <code>password</code>, <code>credential</code></td></tr></tbody></table>`,42)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};